args.CommandLine:
python3 -c '
import unicodedata

items = [
    ["൱", "൲", "൳", "൴", "൵", "൶"],
    ["🃖", "🃗", "🃘"],
    ["🞨", "🞩", "🞪", "🞫", "🞬"]
]

for i, seq in enumerate(items):
    print(f"Item {i}:")
    for ch in seq:
        print(f"  {ch} U+{ord(ch):04X} {unicodedata.name(ch, \"?\")}")
    last = ord(seq[-1])
    print("  Next 5 codepoints:")
    for n in range(last + 1, last + 6):
        try:
            print(f"    {chr(n)} U+{n:04X} {unicodedata.name(chr(n))}")
        except Exception as e:
            print(f"    U+{n:04X} {e}")
'

